<script setup>
import UiMoneyInput from '~/components/ui/MoneyInput.vue'
import { money, today } from '#shared/utils/format.js'
import { SOURCES } from '#shared/constants/index.js'
const props = defineProps({ order: Object })
const { toast, error } = useFeedback()
const {isLocationAdmin,user}=useAuth()
const { data: options, refresh:refreshOptions }=await useFetch('/api/orders/options',{immediate:isLocationAdmin.value})
const { data: customers } = isLocationAdmin.value?{data:computed(()=>options.value?.customers||[])}:await useCustomers()
const { data: services } = isLocationAdmin.value?{data:computed(()=>options.value?.services||[])}:await useFetch('/api/services',{default:()=>[]})
const { data: locations } = isLocationAdmin.value?{data:computed(()=>options.value?.locations||[])}:await useFetch('/api/locations',{default:()=>[]})
const { data: billing } = isLocationAdmin.value?{data:computed(()=>options.value?.billing)}:await useFetch('/api/settings/billing')
const form = reactive({ customerId:props.order?.customerId || '',customerAddressId:props.order?.customerAddressId || null,locationId:props.order?.locationId || (isLocationAdmin.value?user.value.locationId||user.value.locationIds[0]:null),bookingDate:props.order?.bookingDate || today(),bookingTime:props.order?.bookingTime?.slice(0,5) || '14:00',address:props.order?.addressSnapshot || '',latitude:props.order?.latitude??null,longitude:props.order?.longitude??null,services:props.order?.items.map(i=>({serviceId:i.serviceId,qty:i.qty})) || [{serviceId:'',qty:1}],discount:Number(props.order?.discount || 0),transportFee:Number(props.order?.transportFee || 0),tax:Number(props.order?.tax || 0),source:props.order?.source || 'WHATSAPP',notes:props.order?.notes || '' })
watch(()=>billing.value, settings=>{if(settings?.transportEnabled===false)form.transportFee=0;if(settings?.taxEnabled===false)form.tax=0},{immediate:true})
const customerOpen=ref(false),customerBusy=ref(false),customerMessage=ref('')
const newCustomer=reactive({name:'',phone:'',email:'',notes:''})
async function saveCustomer(){customerBusy.value=true;customerMessage.value='';try{const created=await $fetch('/api/orders/customer',{method:'POST',body:newCustomer});await refreshOptions();form.customerId=created.id;customerOpen.value=false;Object.assign(newCustomer,{name:'',phone:'',email:'',notes:''})}catch(e){customerMessage.value=error(e)}finally{customerBusy.value=false}}
const pin=computed({get:()=>({latitude:form.latitude,longitude:form.longitude}),set:point=>{form.latitude=point?.latitude??null;form.longitude=point?.longitude??null}})
function selectAddress(address){form.address=address.address;form.customerAddressId=address.id;form.latitude=address.latitude??null;form.longitude=address.longitude??null}
const busy=ref(false);const message=ref('');const addresses=ref([])
const requestFetch=useRequestFetch()
watch(()=>form.customerId,async (id,previousId)=>{
  addresses.value=[]
  const preserveSnapshot=previousId===undefined&&props.order&&Number(id)===props.order.customerId
  if(!preserveSnapshot){form.customerAddressId=null;form.latitude=null;form.longitude=null}
  if(id){try{
    const customer=isLocationAdmin.value?customers.value.find(c=>c.id===Number(id)):await requestFetch(`/api/customers/${id}`)
    if(Number(form.customerId)!==Number(id))return
    addresses.value=customer?.addresses||[]
    const address=addresses.value.find(a=>a.isDefault)
    if(address&&!preserveSnapshot)selectAddress(address)
  }catch(e){message.value=error(e)}}
},{immediate:true})
function useAddress() { const address=addresses.value.find(a=>a.id===form.customerAddressId);if(address)selectAddress(address);else{form.latitude=null;form.longitude=null} }
function price(item) { const service=services.value.find(s=>s.id===Number(item.serviceId));return Number(service?.prices.find(p=>p.isActive&&p.locationId===form.locationId)?.price ?? service?.prices.find(p=>p.isActive&&p.locationId===null)?.price ?? 0) }
const subtotal=computed(()=>form.services.reduce((n,i)=>n+price(i)*i.qty,0))
const total=computed(()=>subtotal.value-Number(form.discount)+(billing.value?.transportEnabled?Number(form.transportFee):0)+(billing.value?.taxEnabled?Number(form.tax):0))
const duration=computed(()=>form.services.reduce((n,i)=>n+(services.value.find(s=>s.id===Number(i.serviceId))?.durationMinutes || 0)*i.qty,0))
async function submit(){busy.value=true;message.value='';try{const order=await $fetch(props.order?`/api/orders/${props.order.id}`:'/api/orders',{method:props.order?'PATCH':'POST',body:{...form,customerId:Number(form.customerId),locationId:form.locationId || null,services:form.services.map(i=>({serviceId:Number(i.serviceId),qty:Number(i.qty)}))}});toast(props.order?'Order diperbarui':'Order berhasil dibuat');await navigateTo('/orders/'+order.id)}catch(e){message.value=error(e)}finally{busy.value=false}}
</script><template><form @submit.prevent="submit"><div class="detail-grid"><div class="space-y-5"><section class="panel form-panel"><h2>Customer & lokasi treatment</h2><div class="form-grid"><label class="full">Customer<select v-model="form.customerId" aria-label="Customer" required><option value="" disabled>Pilih customer</option><option v-for="c in customers" :key="c.id" :value="c.id">{{ c.name }} · {{ c.phone }}</option></select><button v-if="isLocationAdmin" type="button" class="text-link" @click="customerOpen=true">Tambah customer baru</button><NuxtLink v-else to="/customers/new" class="text-link">+ Tambah customer baru</NuxtLink></label><label>Lokasi / cabang<select v-model="form.locationId" aria-label="Lokasi / cabang"><option v-if="!isLocationAdmin" :value="null">Tentukan nanti</option><option v-for="l in locations.filter(l=>l.isActive)" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label>Sumber booking<select v-model="form.source" aria-label="Sumber booking"><option v-for="s in SOURCES" :key="s" :value="s">{{ s }}</option></select></label><label v-if="addresses.length" class="full">Alamat tersimpan<select v-model="form.customerAddressId" aria-label="Alamat tersimpan" @change="useAddress"><option :value="null">Alamat lainnya</option><option v-for="a in addresses" :key="a.id" :value="a.id">{{ a.label }} · {{ a.address }}</option></select></label><label class="full">Alamat treatment<textarea v-model="form.address" required minlength="3" rows="3" placeholder="Nama hotel/villa, nomor kamar, dan alamat lengkap" /></label><div class="full"><LocationPicker v-model="pin" :address="form.address" /></div></div></section><section class="panel form-panel"><h2>Treatment & jadwal</h2><div class="form-grid"><label>Tanggal<input v-model="form.bookingDate" type="date" required /></label><label>Waktu mulai<input v-model="form.bookingTime" type="time" required /></label></div><div v-for="(item,i) in form.services" :key="i" class="service-form-row"><label>Layanan<select v-model="item.serviceId" aria-label="Layanan" required><option value="" disabled>Pilih treatment</option><option v-for="s in services.filter(s=>s.isActive)" :key="s.id" :value="s.id">{{ s.name }} · {{ s.durationMinutes }} menit</option></select></label><label>Qty<input v-model.number="item.qty" type="number" min="1" max="10" required /></label><span>{{ money(price(item)*item.qty) }}</span><button v-if="form.services.length>1" class="icon-button" type="button" aria-label="Hapus layanan" @click="form.services.splice(i,1)"><UiIcon name="close" :size="17" /></button></div><UiButton variant="secondary" @click="form.services.push({serviceId:'',qty:1})"><UiIcon name="plus" :size="16" />Tambah layanan</UiButton><p class="form-hint">Durasi total: {{ duration }} menit. Qty dihitung sebagai treatment berurutan.</p></section><section class="panel form-panel"><h2>Catatan</h2><label><textarea v-model="form.notes" rows="3" placeholder="Preferensi customer atau instruksi untuk therapist" /></label></section></div><aside class="panel form-panel sticky-panel"><h2>Ringkasan order</h2><div class="billing-line"><span>Subtotal</span><strong>{{ money(subtotal) }}</strong></div><label>Diskon (Rp)<UiMoneyInput v-model="form.discount" :max="subtotal" required /></label><label v-if="billing?.transportEnabled">Biaya transport (Rp)<UiMoneyInput v-model="form.transportFee" required /></label><label v-if="billing?.taxEnabled">Pajak (Rp)<UiMoneyInput v-model="form.tax" required /></label><div class="billing-total"><span>Total</span><strong>{{ money(total) }}</strong></div><p class="form-hint">Nama layanan dan harga disimpan sebagai snapshot saat order disimpan.</p><p v-if="message" role="alert" class="error-message">{{ message }}</p><UiButton type="submit" class="w-full" :loading="busy">{{ order?'Simpan perubahan':'Buat order' }}<UiIcon name="arrow" :size="16" /></UiButton><UiButton to="/orders" variant="ghost" class="w-full">Batal</UiButton></aside></div></form><UiModal :open="customerOpen" title="Customer untuk order" @close="customerOpen=false"><form @submit.prevent="saveCustomer"><label>Nama customer<input v-model="newCustomer.name" required minlength="2" /></label><label>WhatsApp customer<input v-model="newCustomer.phone" type="tel" required /></label><label>Email customer<input v-model="newCustomer.email" type="email" /></label><label>Catatan customer<textarea v-model="newCustomer.notes" rows="2" /></label><p v-if="customerMessage" role="alert" class="error-message">{{ customerMessage }}</p><div class="modal-actions"><UiButton variant="secondary" @click="customerOpen=false">Batal</UiButton><UiButton type="submit" :loading="customerBusy">Simpan customer untuk order</UiButton></div></form></UiModal></template>